def parse_timestamp(value: object, context: str) -> datetime:
    """Parse an ISO 8601 timestamp that must carry explicit timezone info.

    The returned datetime is timezone-aware so it can be compared with UTC
    instants. Naive timestamps are rejected because their meaning is
    ambiguous.
    """
    if not isinstance(value, str) or not value.strip():
        raise ValueError(f"{context}必须为非空时间字符串")
    text = value.strip()
    try:
        parsed = datetime.fromisoformat(text)
    except ValueError as error:
        raise ValueError(f"{context}时间无效: {text!r}") from error
    if parsed.tzinfo is None or parsed.utcoffset() is None:
        raise ValueError(f"{context}必须带有时区信息: {text!r}")
    return parsed.astimezone(timezone.utc)


def format_timestamp(moment: datetime) -> str:
    """Render a datetime as a canonical fixed-length UTC string.

    All instants are stored in this one form (``...Z``, six-digit
    microseconds), so lexicographic string comparison in SQL and Python is
    strictly chronological.
    """
    if moment.tzinfo is None:
        moment = moment.replace(tzinfo=timezone.utc)
    return moment.astimezone(timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.%fZ")


def normalize_pypi_name(name: str) -> str:
    """Normalize a PyPI package name per PEP 503.

    Case is folded and runs of hyphens, underscores and dots are treated as
    equivalent. Component identities are kept verbatim; this normalization
    is only used to match OSV records against components.
    """
    return re.sub(r"[-_.]+", "-", name).lower()


def _parse_pep440_version(value: object, context: str) -> Version:
    if not isinstance(value, str) or not value.strip():
        raise ValueError(f"{context} 必须为非空字符串")
    try:
        return Version(value.strip())
    except InvalidVersion as error:
        raise ValueError(f"无法解析的版本 {value!r}（{context}）") from error


def _parse_withdrawn(value: object) -> str:
    if not isinstance(value, str) or not value.strip():
        raise ValueError("withdrawn 必须为非空时间戳字符串")
    timestamp = value.strip()
    try:
        datetime.fromisoformat(timestamp)
    except ValueError as error:
        raise ValueError(f"withdrawn 时间戳无效: {timestamp!r}") from error
    return timestamp


def _osv_entry_package(entry: object, index: int) -> tuple[str, str]:
    """Validate one affected entry's package target.

    Returns the declared (stripped) package name and its normalized PyPI
    form. Only PyPI entries are accepted; anything else rejects the import.
    """
    if not isinstance(entry, dict):
        raise ValueError(f"affected[{index}] 必须为对象")
    package = entry.get("package")
    if not isinstance(package, dict):
        raise ValueError(f"affected[{index}].package 必须为对象")
    ecosystem = package.get("ecosystem")
    if not isinstance(ecosystem, str) or not ecosystem.strip():
        raise ValueError(f"affected[{index}].package.ecosystem 必须为非空字符串")
    if ecosystem.strip().lower() != "pypi":
        raise ValueError(
            f"affected[{index}] 的生态系统 {ecosystem!r} 不受支持，仅支持 PyPI"
        )
    name = package.get("name")
    if not isinstance(name, str) or not name.strip():
        raise ValueError(f"affected[{index}].package.name 必须为非空字符串")
    raw_name = name.strip()
    return raw_name, normalize_pypi_name(raw_name)


def _osv_explicit_conditions(entry: dict, index: int) -> list[dict]:
    """The explicit-version conditions declared by one affected entry."""
    conditions: list[dict] = []
    versions = entry.get("versions", [])
    if not isinstance(versions, list):
        raise ValueError(f"affected[{index}].versions 必须为数组")
    for version in versions:
        parsed = _parse_pep440_version(version, f"affected[{index}].versions")
        conditions.append({"type": "explicit", "version": str(parsed)})
    return conditions


def _osv_intervals_from_events(events: object, range_context: str) -> list[dict]:
    """Interpret one range's event list as version intervals.

    An ``introduced`` event opens a new interval; a ``fixed`` or
    ``last_affected`` event closes the currently open one. Any other order
    (a second ``introduced`` while one is open, or a closing event with no
    open interval) is rejected, as are unknown event types and events that
    are not exactly one field. ``range_context`` locates the range in error
    messages (``affected[i].ranges[j]``).
    """
    if not isinstance(events, list) or not events:
        raise ValueError(f"{range_context}.events 必须为非空数组")
    intervals: list[dict] = []
    opened = False
    for event_index, event in enumerate(events):
        event_context = f"{range_context}.events[{event_index}]"
        if not isinstance(event, dict):
            raise ValueError(f"{event_context} 必须为对象")
        keys = set(event.keys())
        if len(keys) != 1:
            raise ValueError(f"{event_context} 必须恰好包含一个事件字段")
        key = next(iter(keys))
        if key not in ("introduced", "fixed", "last_affected"):
            raise ValueError(f"{event_context} 的事件类型 {key!r} 不受支持")
        value = event[key]
        if not isinstance(value, str) or not value.strip():
            raise ValueError(f"{event_context}.{key} 必须为非空字符串")
        value = value.strip()
        if key == "introduced":
            if opened:
                raise ValueError(
                    f"{event_context} "
                    "事件次序非法：introduced 之后不能再次 introduced"
                )
            intervals.append(
                {"type": "interval", "introduced": value,
                 "fixed": None, "last_affected": None}
            )
            opened = True
        else:
            if not opened:
                raise ValueError(
                    f"{event_context} 事件次序非法：{key} 之前缺少 introduced"
                )
            intervals[-1][key] = value
            opened = False
    return intervals


def _validate_osv_interval(interval: dict, range_context: str) -> None:
    """Check one interval's versions parse and its bounds are not inverted.

    ``introduced`` of ``"0"`` means no lower bound and is exempt from both
    parsing and the inversion comparisons.
    """
    introduced = interval["introduced"]
    if introduced != "0":
        _parse_pep440_version(introduced, f"{range_context}.introduced")
    if interval["fixed"] is not None:
        fixed = interval["fixed"]
        _parse_pep440_version(fixed, f"{range_context}.fixed")
        if introduced != "0" and not (Version(introduced) < Version(fixed)):
            raise ValueError(
                f"{range_context} 区间倒置："
                f"introduced {introduced} 必须小于 fixed {fixed}"
            )
    if interval["last_affected"] is not None:
        last_affected = interval["last_affected"]
        _parse_pep440_version(last_affected, f"{range_context}.last_affected")
        if introduced != "0" and not (
            Version(introduced) <= Version(last_affected)
        ):
            raise ValueError(
                f"{range_context} 区间倒置："
                f"introduced {introduced} 不能大于 last_affected {last_affected}"
            )


def _osv_range_conditions(entry: dict, index: int) -> list[dict]:
    """The interval conditions declared by one affected entry's ranges."""
    conditions: list[dict] = []
    ranges = entry.get("ranges", [])
    if not isinstance(ranges, list):
        raise ValueError(f"affected[{index}].ranges 必须为数组")
    for range_index, range_entry in enumerate(ranges):
        range_context = f"affected[{index}].ranges[{range_index}]"
        if not isinstance(range_entry, dict):
            raise ValueError(f"{range_context} 必须为对象")
        range_type = range_entry.get("type")
        if not isinstance(range_type, str) or not range_type.strip():
            raise ValueError(f"{range_context}.type 必须为非空字符串")
        if range_type.strip().upper() != "ECOSYSTEM":
            raise ValueError(
                f"{range_context} 的范围类型 {range_type!r} 不受支持，仅支持 ECOSYSTEM"
            )
        intervals = _osv_intervals_from_events(
            range_entry.get("events"), range_context
        )
        for interval in intervals:
            _validate_osv_interval(interval, range_context)
        conditions.extend(intervals)
    return conditions


def _parse_osv_entry(entry: object, index: int) -> tuple[str, list[dict]]:
    """Validate one affected entry and return its package and conditions.

    Every entry must independently declare at least one version condition —
    a non-empty explicit versions list or at least one valid ECOSYSTEM
    range. Conditions are never shared between entries, so an entry without
    its own conditions rejects the import no matter what any identically or
    equivalently named sibling entry declares.
    """
    raw_name, package_name = _osv_entry_package(entry, index)
    conditions = _osv_explicit_conditions(entry, index)
    conditions.extend(_osv_range_conditions(entry, index))
    if not conditions:
        raise ValueError(
            f"affected[{index}]（包 {raw_name}）缺少版本条件："
            "必须提供非空 versions 或至少一个合法 ECOSYSTEM ranges"
        )
    return package_name, conditions


def _parse_osv_affected(affected: object) -> dict[str, list[dict]]:
    """Validate the affected entries of one OSV record.

    Returns a mapping of normalized package name to the version conditions
    declared for that package, merged across every entry targeting the same
    normalized name. Merging only ever combines conditions of entries that
    each validated on their own; identical or normalization-equivalent
    package names never let one entry borrow another entry's conditions.
    Other ecosystems, unknown range types/events, malformed event orders,
    inverted intervals and unparseable versions reject the whole import.
    """
    if not isinstance(affected, list) or not affected:
        raise ValueError("affected 必须为非空数组")
    packages: dict[str, list[dict]] = {}
    for index, entry in enumerate(affected):
        package_name, conditions = _parse_osv_entry(entry, index)
        packages.setdefault(package_name, []).extend(conditions)
    return packages


def parse_osv_record(record: object) -> list[dict]:
    """Validate one OSV record and return its normalized rows.

    Each returned row describes one (package, version conditions) pair. The
    whole record is validated before anything is returned, so callers can
    reject the entire import on the first invalid record.
    """
    if not isinstance(record, dict):
        raise ValueError("记录必须为 JSON 对象")
    identifier = record.get("id")
    if not isinstance(identifier, str) or not identifier.strip():
        raise ValueError("id 必须为非空字符串")
    identifier = identifier.strip()

    packages = _parse_osv_affected(record.get("affected"))

    severity = "medium"
    severity_default = True
    database_specific = record.get("database_specific")
    if database_specific is not None:
        if not isinstance(database_specific, dict):
            raise ValueError("database_specific 必须为对象")
        declared = database_specific.get("severity")
        if declared is not None:
            if not isinstance(declared, str) or declared.strip().lower() not in SEVERITY_RANK:
                raise ValueError(
                    f"database_specific.severity {declared!r} 不受支持，"
                    "仅接受 low、medium、high、critical"
                )
            severity = declared.strip().lower()
            severity_default = False

    withdrawn = None
    if "withdrawn" in record:
        withdrawn = _parse_withdrawn(record["withdrawn"])

    return [
        {
            "id": identifier,
            "package_name": package_name,
            "severity": severity,
            "severity_default": severity_default,
            "withdrawn": withdrawn,
            "conditions": conditions,
        }
        for package_name, conditions in packages.items()
    ]


def _condition_matches(condition: dict, version: Version) -> bool:
    if condition["type"] == "explicit":
        return version == Version(condition["version"])
    if condition["type"] != "interval":
        return False
    introduced = condition["introduced"]
    if introduced != "0" and version < Version(introduced):
        return False
    if condition["fixed"] is not None and version >= Version(condition["fixed"]):
        return False
    if condition["last_affected"] is not None and version > Version(
        condition["last_affected"]
    ):
        return False
    return True


def _format_condition(condition: dict) -> str:
    if condition["type"] == "explicit":
        return f"=={condition['version']}"
    parts: list[str] = []
    introduced = condition["introduced"]
    if introduced != "0":
        parts.append(f">={introduced}")
    if condition["fixed"] is not None:
        parts.append(f"<{condition['fixed']}")
    if condition["last_affected"] is not None:
        parts.append(f"<={condition['last_affected']}")
    return ",".join(parts) if parts else "*"


@dataclass(frozen=True)
class Summary:
    components: int
    affected_components: int
    vulnerabilities: int
    highest_severity: str | None


def _impact_sort_key(record: dict) -> tuple:
    """Deterministic ordering shared by impact and the risk report."""
    component = record["component"]
    return (
        component["service"],
        component["ecosystem"],
        component["name"],
        component["version"],
        record["vulnerability"],
        record["matched_name"],

        record["source"] or "",
    )


# The exact target of an exemption request: the affected component identity
# (service, ecosystem, name, version), the vulnerability id, the package name
# the vulnerability was matched against, and the vulnerability source — None
# for a manually registered vulnerability, the source name for an imported
# OSV record. The seven fields identify exactly one impact record; nothing
# else (dependency paths, name similarity, version spellings) participates.
ScopeT = tuple[str, str, str, str, str, str, str | None]
_SCOPE_FIELDS: tuple[str, ...] = (
    "service", "ecosystem", "name", "version",
    "vulnerability", "matched_name", "source",
)


def _scope_matches_record(scope: ScopeT, record: dict) -> bool:
    """Whether one exemption scope names exactly this impact record.

    This is the single scope-equality rule shared by request submission,
    approval re-confirmation and report linking. Comparison is verbatim:
    PyPI name normalization only ever matches OSV records against
    components, it never expands a component identity or a pinned matched
    package, so case, version spelling and similar names stay distinct. A
    ``None`` source (manual vulnerability) never equals a named OSV source,
    and two named sources are judged independently even when the
    vulnerability id and package agree.
    """
    component = record["component"]
    return (
        component["service"] == scope[0]
        and component["ecosystem"] == scope[1]
        and component["name"] == scope[2]
        and component["version"] == scope[3]
        and record["vulnerability"] == scope[4]
        and record["matched_name"] == scope[5]
        and record["source"] == scope[6]
    )


def _scope_of_record(record: dict) -> ScopeT:
    """The exemption scope that targets exactly this impact record.

    The scope returned here is the same shape stored on requests and matched
    by :func:`_scope_matches_record`, so a request's stored scope always
    reads back identically to the scope of its corresponding report record.
    """
    component = record["component"]
    return (
        component["service"],
        component["ecosystem"],
        component["name"],
        component["version"],
        record["vulnerability"],
        record["matched_name"],
        record["source"],
    )


@dataclass(frozen=True)
class ImportResult:
    source_components: int
    added_components: int
    deleted_components: int
    added_dependencies: int
    deleted_dependencies: int


_HEX_DIGITS = frozenset("0123456789abcdefABCDEF")


def _decode_percent_escapes(value: str, context: str) -> str:
    """Decode percent-escapes in a single pass, rejecting anything broken.

    Every ``%`` must introduce exactly two hexadecimal digits, and the
    decoded byte sequence must be valid UTF-8. ``urllib.parse.unquote``
    cannot be used here: it silently keeps broken escapes and replaces
    undecodable bytes with U+FFFD, which would let corrupt input register
    as a component identity and merge distinct raw names into one.
    Decoding happens exactly once, so a ``%`` produced by decoding (from
    ``%25``) is literal text, not a new escape.
    """
    if "%" not in value:
        return value
    raw = bytearray()
    index = 0
    while index < len(value):
        char = value[index]
        if char == "%":
            escape = value[index + 1 : index + 3]
            if len(escape) != 2 or any(c not in _HEX_DIGITS for c in escape):
                raise ValueError(f"{context}包含非法的百分号转义: {value!r}")
            raw.append(int(escape, 16))
            index += 3
        else:
            raw.extend(char.encode("utf-8"))
            index += 1
    try:
        return raw.decode("utf-8")
    except UnicodeDecodeError as error:
        raise ValueError(
            f"{context}的编码字节无法还原为 UTF-8 文本: {value!r}"
        ) from error


def parse_purl(purl: object) -> tuple[str, str, str]:
    """Return (ecosystem, name, version) from a Package URL.

    Percent-encoding is decoded strictly — every ``%`` must introduce two
    hexadecimal digits and the decoded bytes must be valid UTF-8 — and npm
    package names keep their scope. The name must be one non-empty segment
    (PyPI, unscoped npm) or two non-empty segments (scoped npm); empty
    segments from consecutive or trailing slashes and segments whose
    decoded text contains a slash are rejected rather than silently
    dropped. Raises ValueError when the purl is missing, malformed,
    unsupported, carries broken percent-encoding or carries no version.
    """
    if not isinstance(purl, str) or not purl:
        raise ValueError("purl 必须为非空字符串")
    if not purl.startswith("pkg:"):
        raise ValueError("purl 必须以 pkg: 开头")
    rest = purl[4:]
    if "/" not in rest:
        raise ValueError("purl 格式无效")
    raw_type, path = rest.split("/", 1)
    ecosystem = _decode_percent_escapes(raw_type, "purl 类型").lower()
    if ecosystem not in SUPPORTED_ECOSYSTEMS:
        raise ValueError(f"不支持的包类型: {ecosystem}")
    # Strip qualifiers (?...) and subpath (#...).
    path = path.split("?", 1)[0].split("#", 1)[0]
    if "@" not in path:
        raise ValueError("purl 缺少版本")
    name_part, version = path.rsplit("@", 1)
    version = _decode_percent_escapes(version, "purl 版本")
    if not version:
        raise ValueError("purl 版本为空")
    # The name's structure is validated before decoding: every segment must
    # be non-empty, so consecutive slashes or a trailing slash before the
    # version separator can never be silently dropped and merge distinct raw
    # names into one component identity.
    raw_segments = name_part.split("/")
    segments: list[str] = []
    for raw_segment in raw_segments:
        if raw_segment == "":
            raise ValueError(f"purl 包名包含空段: {name_part!r}")
        segment = _decode_percent_escapes(raw_segment, "purl 包名")
        # A decoded slash would smuggle extra hierarchy into a name segment
        # (e.g. %2F); decoding happens exactly once, so a literal %2F text
        # produced by %252F is not re-examined and stays valid.
        if "/" in segment:
            raise ValueError(f"purl 包名段还原后包含斜线: {raw_segment!r}")
        segments.append(segment)
    if ecosystem == "npm":
        if len(segments) == 1:
            name = segments[0]
        elif len(segments) == 2:
            name = segments[0] + "/" + segments[1]
        else:
            raise ValueError("npm purl 格式无效")
    else:
        if len(segments) != 1:
            raise ValueError("pypi purl 不应包含命名空间")
        name = segments[0]
    return ecosystem, name, version


# A component identity: (ecosystem, name, version) taken from its purl.
_Identity = tuple[str, str, str]
# A dependency edge between two component identities: (dependent, dependency).
_Edge = tuple[_Identity, _Identity]


class _SbomGraph:
    """Component identities and dependency edges declared by one SBOM document.

    Both formats share these rules: every document reference maps to a
    component identity; several references may declare the same identity and
    then merge into a single catalog component; dependency edges are recorded
    between the merged identities, each identity pair only once, so reference
    names and document order never change the resulting catalog. Cycles
    between distinct identities are allowed, but an edge whose endpoints
    merge into the same identity is a self-dependency and rejects the import.
    """

    def __init__(self) -> None:
        self.identities: dict[str, _Identity] = {}
        self.edges: set[_Edge] = set()

    def ensure_unique(self, ref: str, duplicate_error: str) -> None:
        """References are unique within a document; duplicates are an error."""
        if ref in self.identities:
            raise ValueError(duplicate_error)

    def register(self, ref: str, identity: _Identity) -> None:
        """Map a document reference to its component identity.

        Mapping several references to the same identity is what merges them
        into one catalog component.
        """
        self.identities[ref] = identity

    def identity_of(self, ref: str, unknown_error: str) -> _Identity:
        """Resolve a document reference to its merged component identity."""
        try:
            return self.identities[ref]
        except KeyError:
            raise ValueError(unknown_error) from None

    def add_edge(
        self, dependent: _Identity, dependency: _Identity, refs: tuple[str, str]
    ) -> None:
        """Record a dependency between two merged identities, once.

        ``refs`` are the document references the identities came from; they
        only serve to point out the offending edge when the endpoints merge
        into a single identity.
        """
        if dependent == dependency:
            raise ValueError(f"合并后产生自依赖: {refs[0]} -> {refs[1]}")
        self.edges.add((dependent, dependency))

    def result(self) -> tuple[set[_Identity], set[_Edge]]:
        return set(self.identities.values()), self.edges


def _purl_identity(purl: object, context: str) -> _Identity:
    """Parse a component's purl, reporting failures with the document position."""
    try:
        return parse_purl(purl)
    except ValueError as error:
        raise ValueError(f"{context} purl 无效: {error}") from error


def _check_declared_version(
    declared: object, purl_version: str, context: str
) -> None:
    """A version field next to the purl must agree with the purl version."""
    if not isinstance(declared, str) or not declared:
        raise ValueError(f"{context} 必须为非空字符串")
    if declared != purl_version:
        raise ValueError(f"{context} 与 purl 版本不一致")


def _parse_sbom(sbom: object) -> tuple[set[_Identity], set[_Edge]]:
    """Validate an SBOM document and return (identities, edges).

    Both CycloneDX 1.5 and SPDX 2.3 JSON are accepted; the format is
    recognized from the document itself. identities is the set of
    (ecosystem, name, version) tuples registered under the importing
    service. edges is a set of (dependent, dependency) identity pairs.
    All validation happens before any database write.
    """
    if not isinstance(sbom, dict):
        raise ValueError("清单必须是 JSON 对象")
    if "spdxVersion" in sbom:
        return _parse_spdx(sbom)
    return _parse_cyclonedx(sbom)


def _parse_cyclonedx(sbom: dict) -> tuple[set[_Identity], set[_Edge]]:
    """Validate a CycloneDX 1.5 SBOM and return (identities, edges)."""
    if sbom.get("bomFormat") != "CycloneDX":
        raise ValueError("bomFormat 必须为 CycloneDX")
    if sbom.get("specVersion") != "1.5":
        raise ValueError("specVersion 必须为 1.5")
    if "components" not in sbom:
        raise ValueError("缺少 components 字段")
    components = sbom["components"]
    if not isinstance(components, list):
        raise ValueError("components 必须为数组")

    root_ref: str | None = None
    metadata = sbom.get("metadata")
    if isinstance(metadata, dict):
        root_component = metadata.get("component")
        if isinstance(root_component, dict) and "bom-ref" in root_component:
            root_ref = root_component["bom-ref"]
            if not isinstance(root_ref, str) or not root_ref:
                raise ValueError("metadata.component.bom-ref 必须为非空字符串")

    graph = _SbomGraph()
    for index, component in enumerate(components):
        if not isinstance(component, dict):
            raise ValueError(f"components[{index}] 必须为对象")
        nested = component.get("components")
        if isinstance(nested, list) and nested:
            raise ValueError(f"components[{index}] 存在嵌套组件，不予登记")
        ref = component.get("bom-ref")
        if not isinstance(ref, str) or not ref:
            raise ValueError(f"components[{index}] 的 bom-ref 必须为非空字符串")
        graph.ensure_unique(ref, f"bom-ref 重复: {ref}")
        if root_ref is not None and ref == root_ref:
            raise ValueError(f"bom-ref 与 metadata.component 根引用冲突: {ref}")
        context = f"components[{index}] (bom-ref {ref})"
        identity = _purl_identity(component.get("purl"), context)
        if "version" in component:
            _check_declared_version(
                component["version"], identity[2], f"{context} version"
            )
        graph.register(ref, identity)

    dependencies = sbom.get("dependencies", [])
    if not isinstance(dependencies, list):
        raise ValueError("dependencies 必须为数组")
    for index, entry in enumerate(dependencies):
        if not isinstance(entry, dict):
            raise ValueError(f"dependencies[{index}] 必须为对象")
        ref = entry.get("ref")
        if not isinstance(ref, str) or not ref:
            raise ValueError(f"dependencies[{index}].ref 必须为非空字符串")
        depends_on = entry.get("dependsOn", [])
        if not isinstance(depends_on, list):
            raise ValueError(f"dependencies[{index}].dependsOn 必须为数组")
        if ref == root_ref:
            # The list root's own outgoing edges are not registered.
            continue
        dependent = graph.identity_of(
            ref, f"dependencies[{index}].ref 引用未知组件: {ref}"
        )
        for target in depends_on:
            if not isinstance(target, str) or not target:
                raise ValueError(
                    f"dependencies[{index}].dependsOn 必须为非空字符串数组"
                )
            if target == root_ref:
                raise ValueError(
                    f"dependencies[{index}] 组件 {ref} 依赖了 metadata.component 根引用"
                )
            dependency = graph.identity_of(
                target, f"dependencies[{index}] 依赖引用未知组件: {target}"
            )
            graph.add_edge(dependent, dependency, (ref, target))

    return graph.result()


def _spdx_purl_identity(package: dict, index: int, ref: str) -> _Identity:
    """Extract a component identity from a package's purl external refs."""
    external_refs = package.get("externalRefs")
    if external_refs is None:
        raise ValueError(f"packages[{index}] (SPDXID {ref}) 缺少 purl 引用")
    if not isinstance(external_refs, list) or not external_refs:
        raise ValueError(f"packages[{index}] (SPDXID {ref}) externalRefs 必须为非空数组")
    identity: _Identity | None = None
    for ref_index, external_ref in enumerate(external_refs):
        if not isinstance(external_ref, dict):
            raise ValueError(
                f"packages[{index}].externalRefs[{ref_index}] 必须为对象"
            )
        if external_ref.get("referenceType") != "purl":
            continue
        candidate = _purl_identity(
            external_ref.get("referenceLocator"),
            f"packages[{index}] (SPDXID {ref})",
        )
        if identity is None:
            identity = candidate
        elif candidate != identity:
            raise ValueError(
                f"packages[{index}] (SPDXID {ref}) 多个 purl 指向不同组件身份"
            )
    if identity is None:
        raise ValueError(f"packages[{index}] (SPDXID {ref}) 缺少 purl 引用")
    return identity


def _parse_spdx(document: dict) -> tuple[set[_Identity], set[_Edge]]:
    """Validate an SPDX 2.3 JSON document and return (identities, edges)."""
    if document.get("spdxVersion") != "SPDX-2.3":
        raise ValueError("spdxVersion 必须为 SPDX-2.3")
    document_spdxid = document.get("SPDXID")
    if not isinstance(document_spdxid, str) or not document_spdxid:
        raise ValueError("文档 SPDXID 必须为非空字符串")
    if "packages" not in document:
        raise ValueError("缺少 packages 字段")
    packages = document["packages"]
    if not isinstance(packages, list):
        raise ValueError("packages 必须为数组")

    graph = _SbomGraph()
    for index, package in enumerate(packages):
        if not isinstance(package, dict):
            raise ValueError(f"packages[{index}] 必须为对象")
        spdxid = package.get("SPDXID")
        if not isinstance(spdxid, str) or not spdxid:
            raise ValueError(f"packages[{index}] SPDXID 必须为非空字符串")
        if spdxid == document_spdxid:
            raise ValueError(f"packages[{index}] SPDXID 与文档标识冲突: {spdxid}")
        graph.ensure_unique(spdxid, f"SPDXID 重复: {spdxid}")
        identity = _spdx_purl_identity(package, index, spdxid)
        if "versionInfo" in package:
            _check_declared_version(
                package["versionInfo"],
                identity[2],
                f"packages[{index}] (SPDXID {spdxid}) versionInfo",
            )
        graph.register(spdxid, identity)

    relationships = document.get("relationships", [])

class Catalog:
    def __init__(self, database: str | Path = ":memory:") -> None:
        self.connection = sqlite3.connect(str(database))
        self.connection.row_factory = sqlite3.Row
        # Let concurrent writers wait for each other; guarded UPDATEs still
        # ensure that two processes processing one request produce at most a
        # single state change.
        self.connection.execute("PRAGMA busy_timeout = 10000")
        self.connection.executescript(SCHEMA)
        self._migrate()

    def _migrate(self) -> None:
        """Add ownership columns to databases created by earlier releases.

        Components and relationships already present are considered manually
        registered, so they survive source replacement.
        """
        component_columns = {
            str(row["name"])
            for row in self.connection.execute("PRAGMA table_info(components)")
        }
        if "manual" not in component_columns:
            self.connection.execute(
                "ALTER TABLE components ADD COLUMN manual INTEGER NOT NULL DEFAULT 0"
            )
            self.connection.execute("UPDATE components SET manual = 1")
        dependency_columns = {
            str(row["name"])
            for row in self.connection.execute("PRAGMA table_info(dependencies)")
        }
        if "manual" not in dependency_columns:
            self.connection.execute(
                "ALTER TABLE dependencies ADD COLUMN manual INTEGER NOT NULL DEFAULT 0"
            )
            self.connection.execute("UPDATE dependencies SET manual = 1")
        self.connection.commit()

    def close(self) -> None:
        self.connection.close()

    @contextmanager
    def _write_tx(self):
        """A serialized write transaction.

        ``BEGIN IMMEDIATE`` takes the database write lock up front, so two
        concurrent processes serialize their check-then-write sequences: the
        second blocks until the first commits and then observes its changes.
        Used for exemption requests and decisions to guarantee that a scope
        never gets two live requests and that a request changes state at most
        once.
        """
        self.connection.execute("BEGIN IMMEDIATE")
        try:
            yield
        except Exception:
            self.connection.rollback()
            raise
        else:
            # The write phase succeeded, but persisting it is itself part of
            # the save: a commit error (e.g. the file database is momentarily
            # held by another read connection, SQLITE_BUSY) can still arrive
            # here. Without this rollback the connection keeps the open,
            # uncommitted transaction, so the very same Catalog object would
            # read the decision back as if it had completed and could not be
            # reused until it was closed and reopened. Roll the partial save
            # back and surface the original database error to the caller.
            try:
                self.connection.commit()
            except Exception:
                self.connection.rollback()
                raise

